SourceCode.Declaration:
internal class GUPItemBasePriceCalcJob_All extends GUPItemBasePriceCalcJob implements BatchRetryable
{
    private guid sessionGuid;

}

Method.Source:
public InventDimId inventDimIdDefault()
{
    if (this.parmSiteId())
    {
        return this.inventDimIdSite();
    }

    return InventDim::inventDimIdBlank();
}

public boolean showItem()
{
    return false;
}

public boolean showQueryValues()
{
    return true;
}

private void initSessionGuid()
{
    sessionGuid = newGuid();
}

public void new()
{
    Query                   query;
    QueryBuildDataSource    queryBuildDataSource;

    query = new Query(queryStr(GUPItemBasePriceCalc));

    queryRun = new QueryRun(query);

    this.initSessionGuid();
    super();
}

public SysGuid parmSessionGuid(SysGuid _sessionGuid = sessionGuid)
{
    sessionGuid = _sessionGuid;

    return sessionGuid;
}

public void deleteTasks()
{
    GUPBasePriceCalcItemTask                    basePriceCalcItemTask;
    GUPBasePriceCalcItemInventDimensionTask     basePriceCalcItemInvenDimensionTask;

    ttsbegin;
    delete_from basePriceCalcItemTask
        where basePriceCalcItemTask.SessionGuid == this.parmSessionGuid();

    delete_from basePriceCalcItemInvenDimensionTask
        where basePriceCalcItemInvenDimensionTask.SessionGuid == this.parmSessionGuid();
    ttscommit;
}

public final void getLast()
{
    QueryBuildDataSource    queryBuildDataSource;
    QueryBuildRange         queryBuildRange;
    super();
    //we don't want to use any stored guids
    this.initSessionGuid();
    queryBuildDataSource = queryRun.query().dataSourceNo(1);
    queryBuildRange = SysQuery::findOrCreateRange(queryBuildDataSource, fieldNum(InventTable, ItemId));
    queryBuildRange.value('');
}

private GUPBasePriceCalcItemTask initBasePriceCalcItemTask(InventTable _inventTable)
{
    GUPBasePriceCalcItemTask basePriceCalcItemTask;

    basePriceCalcItemTask.initFromInventTable(_inventTable);
    basePriceCalcItemTask.SessionGuid = sessionGuid;

    return basePriceCalcItemTask;
}

protected boolean skipDimCombination(Enumerator _productDims, InventTable _inventTable, InventDim _inventDimCombinationDim)
{
    if (!_inventTable.ItemDimCostPrice)
    {
        _productDims.reset();
        while (_productDims.moveNext())
        {
            InventProductDimension productDim = _productDims.current() as InventProductDimension;
            anytype defaultValue = productDim.parmDefaultValueForItem(_inventTable);
            if (defaultValue)
            {
                FieldId fieldId = productDim.parmInventDimFieldId();
                if (defaultValue != _inventDimCombinationDim.(fieldId))
                {
                    return true;
                }
            }
        }
    }
    return false;
}

protected void runBasePriceCalculation()
{
    this.updateProgress();
    super();
}

protected void runSequential()
{
    InventDimId                                 defaultDimId;
    GUPBasePriceCalcItemTask                    basePriceCalcItemTask;
    GUPBasePriceCalcItemInventDimensionTask     basePriceCalcItemInvenDimensionTask;
    defaultDimId = this.inventDimIdDefault();

    while select ItemId from basePriceCalcItemTask
        where basePriceCalcItemTask.SessionGuid   == this.parmSessionGuid()
    outer join RecId, InventDimId from basePriceCalcItemInvenDimensionTask
        where basePriceCalcItemInvenDimensionTask.basePriceCalcItemTask == basePriceCalcItemTask.RecId
    {
        try
        {
            this.parmItemId(basePriceCalcItemTask.ItemId);

            //there were InventDimCombinations for the item that has to be processed
            if (basePriceCalcItemInvenDimensionTask.RecId)
            {
                this.parmInventDimId(basePriceCalcItemInvenDimensionTask.InventDimId);
            }
            else
            {
                this.parmInventDimId(defaultDimId);
            }

            this.runBasePriceCalculation();
        }
        catch (Exception::Error)
        {
            exceptionTextFallThrough();
        }
    }

    this.deleteTasks();
}

protected int64 prepareTasksForSelectedItems()
{
    InventDimCombination                        inventDimCombination;
    InventTable                                 localInventTable;
    GUPBasePriceCalcItemInventDimensionTask     basePriceCalcItemInvenDimensionTask;
    GUPBasePriceCalcItemTask                    basePriceCalcItemTask;
    RecordInsertList                            rilBasePriceCalcItemTask;
    RecordInsertList                            rilBasePriceCalcItemInventDimensionTask;
    int64                                       numberOfTasksCreated = 0;
    InventDim                                   inventDimCombinationDim;
    InventDim                                   inventDimCombinationDimWithSite;
    boolean                                     foundAnyWithActiveProductDimensions;

    rilBasePriceCalcItemTask = new RecordInsertList(tableNum(GUPBasePriceCalcItemTask));

    while (queryRun.next())
    {
        localInventTable = queryRun.get(tableNum(InventTable), 1);

        basePriceCalcItemTask = this.initBasePriceCalcItemTask(localInventTable);

        if (localInventTable.hasProductDimensions())
        {
            //there can be cases where we have an item with active product dimensions and no inventdimcombinations, but for this edge case we accept a small overhead of doing calculations for that item
            basePriceCalcItemTask.HasActiveProductDimensions  = NoYes::Yes;
            foundAnyWithActiveProductDimensions = true;
        }

        rilBasePriceCalcItemTask.add(basePriceCalcItemTask);
        numberOfTasksCreated++;
    }

    //ensure that all basePriceCalcItemTask are inserted before we create any basePriceCalcItemInvenDimensionTask
    rilBasePriceCalcItemTask.insertDatabase();

    if (foundAnyWithActiveProductDimensions)
    {
        rilBasePriceCalcItemInventDimensionTask = new RecordInsertList(tableNum(GUPBasePriceCalcItemInventDimensionTask));

        InventDistinctProduct inventDistinctProduct;
        Enumerator productDims = InventProductDimension::getEnumeratorForEnabledDimensions();

        while select basePriceCalcItemTask order by basePriceCalcItemTask.ItemId, inventDistinctProduct.Level desc
            where basePriceCalcItemTask.SessionGuid                   == sessionGuid
            &&    basePriceCalcItemTask.HasActiveProductDimensions    == NoYes::Yes
        join TableId from inventDimCombination
            where inventDimCombination.ItemId == basePriceCalcItemTask.ItemId
        join inventDimCombinationDim
            where inventDimCombinationDim.InventDimId == inventDimCombination.InventDimId
        join Level from inventDistinctProduct
            where inventDistinctProduct.ItemId == basePriceCalcItemTask.ItemId
            &&    inventDistinctProduct.ItemId == inventDimCombination.ItemId
            &&    inventDistinctProduct.InventDimId == inventDimCombination.InventDimId
        join localInventTable
            where localInventTable.ItemId == basePriceCalcItemTask.ItemId
        {
            basePriceCalcItemInvenDimensionTask.clear();
            basePriceCalcItemInvenDimensionTask.initFromBasePriceCalcItemTask(basePriceCalcItemTask);
            //create an inventdim with the product dimensions and site
            inventDimCombinationDimWithSite.clear();
            inventDimCombinationDimWithSite.data(inventDimCombinationDim);
            inventDimCombinationDimWithSite.InventSiteId = this.parmSiteId();
            inventDimCombinationDimWithSite = InventDim::findOrCreate(inventDimCombinationDimWithSite);
            basePriceCalcItemInvenDimensionTask.InventDimId = inventDimCombinationDimWithSite.InventDimId;
            rilBasePriceCalcItemInventDimensionTask.add(basePriceCalcItemInvenDimensionTask);
        }

        rilBasePriceCalcItemInventDimensionTask.insertDatabase();
    }

    return numberOfTasksCreated;

}

private void updateProgress()
{
    if (!progress || !inventDimId)
    {
        return;
    }

    progress.setText(strFmt("@SYS24300",itemId));

    progress.incCount();
}

public static GUPItemBasePriceCalcJob_All construct()
{
    return new GUPItemBasePriceCalcJob_All();
}

public static ClassDescription description()
{
    return "@SYS343262";
}

protected boolean canRunInNewSession()
{
    return true;
}

[Hookable(false)]
final public boolean isRetryable()
{
    return false;
}

public void run()
{
    ttsbegin; //the task data has to be committed for the parallel run to work on it
    int64 numberOfTasksToProcess = this.prepareTasksForSelectedItems();
    ttscommit;

    if (!numberOfTasksToProcess)
    {
        return;
    }

    this.progressInit("@SYS13118", numberOfTasksToProcess, #AviUpdate);
    progress.setCount(1);

    this.initBasePriceRawData();
    this.runSequential();
}

private void initBasePriceRawData()
{
    GUPBasePriceRawData basePriceRawDataLocal = GUPBasePriceRawDataProvider::instance(this.parmSiteId(), this.parmCalcDate()).initializeBasePriceRawData();
    this.parmBasePriceRawData(basePriceRawDataLocal);
}
